package com.slotmind.repository; import com.slotmind.entity.*; import com.slotmind.enums.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface AppointmentRepository extends JpaRepository<Appointment,String> { List<Appointment> findByStatus(AppointmentStatus status); List<Appointment> findByProviderAndStatus(Provider p, AppointmentStatus s); List<Appointment> findByProvider_IdAndStatus(String providerId, AppointmentStatus status); Optional<Appointment> findBySlot(Slot slot); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Appointment a where a.id=:id") Optional<Appointment> lockById(String id); }